                index = rng.randint(-10, -1)
            elif choice < 0.8 and arr_len > 0:
                # Valid index
                index = rng.randint(0, arr_len - 1)
            else:
                # Out-of-bounds index
                index = rng.randint(arr_len, arr_len + 10)
        else:
            # Edge/bug cases:
            # Notice the upstream fix checked `elif index in array:` instead of index in range(len(array)) or len check!
            # So if index >= len(array) and index is an element of array (or not), behavior diverges (IndexError vs default).
            choice = rng.random()
            if choice < 0.5:
                # Out of bounds index that is in array or not in array
                index = rng.randint(arr_len, arr_len + 10)
                if rng.random() < 0.5 and arr_len > 0:
                    # Intentionally put index into array to trigger index in array while index >= len(array)
                    array.append(index)
                    rng.shuffle(array)
            elif choice < 0.8:
                # Out-of-bounds indices specifically around boundary: arr_len, arr_len + 1
                index = arr_len + rng.choice([0, 1, 2])
            else:
                # Empty array edge case
                array = []
                index = rng.randint(0, 5)

        # Decide whether to pass default as kwarg or positional or omit
        kw = rng.choice(["none", "pos", "kw"])
        if kw == "none":
            args = (array, index)
            kwargs = {}
        elif kw == "pos":
            args = (array, index, default)
            kwargs = {}
        else:
            args = (array, index)
            kwargs = {"default": default}

        items.append((None, args, kwargs))

    return items
